import { readFileSync, realpathSync } from 'node:fs';
import { pathToFileURL } from 'node:url';

const compare = (a, b) => a < b ? -1 : a > b ? 1 : 0;
const validId = id => typeof id === 'string' && id.length > 0;

export function planJobs(spec) {
  if (!Array.isArray(spec)) throw new Error('Expected an array of jobs');
  const jobs = new Map();
  for (const job of spec) {
    if (job === null || typeof job !== 'object' || Array.isArray(job) ||
        !validId(job.id) || !Array.isArray(job.deps) ||
        !['pending', 'succeeded', 'failed'].includes(job.state)) {
      throw new Error('Invalid job fields');
    }
    if (jobs.has(job.id)) throw new Error('Duplicate job ID');
    const deps = new Set();
    for (const dep of job.deps) {
      if (!validId(dep) || deps.has(dep)) throw new Error('Invalid or duplicate dependency');
      deps.add(dep);
    }
    jobs.set(job.id, { id: job.id, deps: [...deps], state: job.state,
      children: [], remaining: deps.size, causes: new Set() });
  }
  for (const job of jobs.values()) {
    for (const dep of job.deps) {
      if (!jobs.has(dep)) throw new Error('Unknown dependency');
      jobs.get(dep).children.push(job.id);
    }
  }

  // Maintain a sorted frontier, including completed jobs. Newly available IDs
  // compete immediately with all other zero-indegree IDs.
  const frontier = [...jobs.values()].filter(job => job.remaining === 0)
    .map(job => job.id).sort(compare);
  const ordered = [];
  while (frontier.length) {
    const id = frontier.shift();
    const job = jobs.get(id);
    ordered.push(id);
    for (const childId of job.children) {
      const child = jobs.get(childId);
      for (const cause of job.causes) child.causes.add(cause);
      if (job.state === 'failed') child.causes.add(id);
      if (--child.remaining === 0) {
        let lo = 0, hi = frontier.length;
        while (lo < hi) {
          const mid = Math.floor((lo + hi) / 2);
          if (compare(frontier[mid], childId) < 0) lo = mid + 1;
          else hi = mid;
        }
        frontier.splice(lo, 0, childId);
      }
    }
  }
  if (ordered.length !== jobs.size) throw new Error('Dependency cycle');

  const order = [], ready = [], blocked = [];
  for (const id of ordered) {
    const job = jobs.get(id);
    if (job.state !== 'pending') continue;
    if (job.causes.size) {
      blocked.push({ id, causes: [...job.causes].sort(compare) });
    } else {
      order.push(id);
      if (job.deps.every(dep => jobs.get(dep).state === 'succeeded')) ready.push(id);
    }
  }
  ready.sort(compare);
  blocked.sort((a, b) => compare(a.id, b.id));
  return { order, ready, blocked };
}

// Resolve the entry path so invoking through a symlink also runs the CLI.
if (process.argv[1] && pathToFileURL(realpathSync(process.argv[1])).href === import.meta.url) {
  try {
    if (process.argv.length !== 3) throw new Error('Usage: node job-plan.js SPECFILE');
    const spec = JSON.parse(readFileSync(process.argv[2], 'utf8'));
    process.stdout.write(JSON.stringify(planJobs(spec)) + '\n');
  } catch (error) {
    process.stderr.write(`${error.message}\n`);
    process.exitCode = 2;
  }
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { mkdtempSync, writeFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { spawnSync } from 'node:child_process';
import { planJobs } from '../job-plan.js';

const job = (id, deps = [], state = 'pending') => ({ id, deps, state });

test('full-graph ordering, current readiness, and no mutation', () => {
  const spec = [job('a', ['z']), job('b'), job('z', [], 'succeeded'), job('c', ['b'])];
  const before = structuredClone(spec);
  for (const item of spec) { Object.freeze(item.deps); Object.freeze(item); }
  Object.freeze(spec);
  assert.deepEqual(planJobs(spec), { order: ['b', 'c', 'a'], ready: ['a', 'b'], blocked: [] });
  assert.deepEqual(spec, before);
});

test('failed ancestry survives both completed states and converging paths', () => {
  const spec = [job('root', [], 'failed'), job('second', ['root'], 'failed'),
    job('success', ['second'], 'succeeded'), job('z', ['success', 'root']),
    job('a', ['z', 'second']), job('clean', [], 'succeeded')];
  assert.deepEqual(planJobs(spec), { order: [], ready: [], blocked: [
    { id: 'a', causes: ['root', 'second'] }, { id: 'z', causes: ['root', 'second'] }
  ] });
});

test('IDs use code-unit order and preserve special strings', () => {
  const ids = ['é', 'z', 'a', 'A', '😀', '\ue000', '__proto__', 'constructor', ' ', ' a '];
  const expected = [...ids].sort();
  const spec = ids.map(id => ({ ...job(id), ignored: true }));
  assert.deepEqual(planJobs(spec), { order: expected, ready: expected, blocked: [] });
  assert.deepEqual(planJobs([job('constructor', ['__proto__']), job('__proto__')]), {
    order: ['__proto__', 'constructor'], ready: ['__proto__'], blocked: []
  });
});

test('all malformed fields and references throw synchronously', () => {
  const invalid = [null, {}, 'jobs', 1, [null], [[]], [1], [{}],
    [{ id: '', deps: [], state: 'pending' }],
    [{ id: 1, deps: [], state: 'pending' }],
    [{ id: 'a', state: 'pending' }],
    [{ id: 'a', deps: null, state: 'pending' }],
    [{ id: 'a', deps: 'a', state: 'pending' }],
    [{ id: 'a', deps: [] }],
    [{ id: 'a', deps: [], state: undefined }],
    [{ id: 'a', deps: [], state: 'Pending' }],
    [job('a', [''])], [job('a', [null])], [job('a', [1])],
    [job('a', ['missing'])], [job('a'), job('a')],
    [job('a'), job('b', ['a', 'a'])], [job('a', Array(1))], Array(1)];
  for (const spec of invalid) assert.throws(() => planJobs(spec), Error);
});

test('cycles are checked even when no pending job participates', () => {
  for (const state of ['pending', 'failed', 'succeeded']) {
    assert.throws(() => planJobs([job('self', ['self'], state)]), Error);
  }
  assert.throws(() => planJobs([job('ok'), job('a', ['b'], 'succeeded'),
    job('b', ['a'], 'failed')]), Error);
});

test('CLI output, argument errors, file errors, JSON errors and graph errors', () => {
  const dir = mkdtempSync(join(tmpdir(), 'job-plan-test-'));
  const script = fileURLToPath(new URL('../job-plan.js', import.meta.url));
  const run = args => spawnSync(process.execPath, [script, ...args], { encoding: 'utf8' });
  const failure = args => {
    const result = run(args);
    assert.equal(result.error, undefined);
    assert.equal(result.status, 2);
    assert.equal(result.stdout, '');
    assert.ok(result.stderr.length > 0);
  };
  try {
    const path = join(dir, 'jobs.json');
    writeFileSync(path, JSON.stringify([job('é')]));
    const result = run([path]);
    assert.equal(result.error, undefined);
    assert.equal(result.status, 0);
    assert.equal(result.stderr, '');
    assert.equal(result.stdout, JSON.stringify({ order: ['é'], ready: ['é'], blocked: [] }) + '\n');
    failure([]);
    failure([path, 'extra']);
    failure([join(dir, 'absent.json')]);
    failure([dir]);
    writeFileSync(path, '{');
    failure([path]);
    writeFileSync(path, JSON.stringify([job('cycle', ['cycle'], 'failed')]));
    failure([path]);
    writeFileSync(path, 'null');
    failure([path]);
    const imported = spawnSync(process.execPath, ['--input-type=module', '-e',
      `await import(${JSON.stringify(new URL('../job-plan.js', import.meta.url).href)})`], { encoding: 'utf8' });
    assert.equal(imported.status, 0);
    assert.equal(imported.stdout, '');
    assert.equal(imported.stderr, '');
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
});

